/// <summary>
/// <c>METCCRDP</c> class holds the logic to run the CCR
/// </summary>
/// CB231_ContainerContentReport
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
public class METCCRDP extends SrsReportDataProviderPreProcessTempDB
{
    METCCRTableTmp      ccrTableTmp;
    RecordInsertList    ccrTableList;

    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// method to get data of table METCCRTableTmp
/// </summary>
/// <returns>METCCRTableTmp</returns>
[SrsReportDataSetAttribute('METCCRTableTmp')]
public METCCRTableTmp getData()
{
    select * from ccrTableTmp;
    return ccrTableTmp;
}

/// <summary>
/// Logic to run the report
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     mETSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      mETSalesOrderShipmentLoadLines;        
    SalesLine                           salesLine;
    METCommonReportContract             contract = this.parmDataContract();

    ccrTableList = new RecordInsertList(tableNum(METCCRTableTmp), true, true, true, true, true, ccrTableTmp);


    while select mETSalesOrderShipmentLoadLines
        where mETSalesOrderShipmentLoadLines.CCRReceived == NoYes::Yes   
        join SalesUnit, InventDimId from salesLine
        where salesLine.InventTransId == mETSalesOrderShipmentLoadLines.InventTransId
        join mETSalesOrderShipmentLoadHeader
            where mETSalesOrderShipmentLoadHeader.ShipmentId == mETSalesOrderShipmentLoadLines.ShipmentId
            && mETSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
    {
        this.insertCCRData(mETSalesOrderShipmentLoadLines.ordernum, mETSalesOrderShipmentLoadLines.ItemId, salesLine);
    }
    ccrTableList.insertDatabase();
}

/// <summary>
/// CCR report data insert
/// </summary>
/// <param name = "_salesOrder">SalesId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_salesLine">SalesLine</param>
public void insertCCRData(SalesId _salesOrder, ItemId _itemId, SalesLine _salesLine)
{
    Qty cartons;
    container conToteId;
    InventLocationName warehouseName;
    METCCRTable metCCRTable;
    DirPartyRecId party;
    const str lineSpace = "\r\n";
    CustTable custTable;

    warehouseName   = InventLocation::find(SalesTable::find(_salesOrder).InventLocationId).Name;

    while select metCCRTable
        where metCCRTable.SalesId == _salesOrder &&
            metCCRTable.ItemId == _itemId
    {
        InventTable     inventTable     = InventTable::find(metCCRTable.ItemId);
        ccrTableTmp.clear();
        ccrTableTmp.ItemDescription     = inventTable.itemName();
        ccrTableTmp.ItemId              = metCCRTable.ItemId;
        ccrTableTmp.CustAccount         = metCCRTable.CustAccount; 

        custTable                       = CustTable::find(metCCRTable.CustAccount);
        party                           = custTable.Party;
        ccrTableTmp.CustAddress         = custTable.name() + lineSpace + METCCRDP::getPostalAddressByType(party, LogisticsLocationRoleType::Delivery);

        ccrTableTmp.QtyPlaced           = metCCRTable.Qty;
        ccrTableTmp.TimeStamp           = DateTimeUtil::newDateTime(metCCRTable.DatePickCompleted, metCCRTable.TimePickCompleted, DateTimeUtil::getUserPreferredTimeZone());

        if (metCCRTable.ToteId =='')
        {
            ccrTableTmp.TotalCartons += ccrTableTmp.QtyPlaced;
        }
        else if (!conFind(conToteId, metCCRTable.ToteId))
        {
            conToteId   += metCCRTable.ToteId;

            ccrTableTmp.TotalCartons     += 1.00;
        }

        if (_salesLine.SalesUnit && _salesLine.inventDimId)
        {
            if (_salesLine.SalesUnit != METConstants::UnitIdEA)
            {
                UnitOfMeasureFromRecId  fromUnit, toUnit;
                fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_salesLine.SalesUnit);
                toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(METConstants::UnitIdEA);

                Factor factor = EcoResProductUnitConverter::convertForReleasedProduct(
                                            _itemId,
                                            _salesLine.inventDimId,
                                            1,
                                            fromUnit,
                                            toUnit,
                                            NoYes::No,
                                            NoYes::No);

                ccrTableTmp.UOM = factor;
            }
            else
            {
                ccrTableTmp.UOM = 1;
            }
        }


        ccrTableTmp.ToteId              = metCCRTable.ToteId;

        ccrTableTmp.WarehouseName       = warehouseName;

        ccrTableTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        ccrTableTmp.CCRHeaderGuidStr = headerReportGuid;
        ccrTableList.add(ccrTableTmp);
    }
}

/// <summary>
/// Method for Item conversion
/// </summary>
/// <param name = "_productRecId">RefRecId</param>
/// <param name = "_fromUnit">Str</param>
/// <returns>UnitOfMeasureConversionFactor</returns>
private UnitOfMeasureConversionFactor getItemConvertionFactor(RefRecId  _productRecId, str _fromUnit)
{
    UnitOfMeasureConversion     unitOfMeasureConversion;
    UnitOfMeasure               toUnitOfMeasure;
    UnitOfMeasure               fromUnitOfMeasure;

    select firstonly unitOfMeasureConversion
        where unitOfMeasureConversion.Product == _productRecId
        join toUnitOfMeasure
            where toUnitOfMeasure.RecId == unitOfMeasureConversion.ToUnitOfMeasure &&
            toUnitOfMeasure.Symbol == METConstants::unitEach
        join fromUnitOfMeasure
            where fromUnitOfMeasure.RecId == unitOfMeasureConversion.FromUnitOfMeasure &&
                fromUnitOfMeasure.Symbol like _fromUnit;

    return unitOfMeasureConversion.Factor;
}

/// <summary>
/// Get postal address
/// </summary>
/// <param name = "_party">DirPartyRecId</param>
/// <param name = "_type">LogisticsLocationRoleType</param>
/// <returns>Addressing</returns>
static Addressing getPostalAddressByType(DirPartyRecId _party, LogisticsLocationRoleType _type)
{
    DirPartyLocation        partyLocation;
    DirPartyLocationRole    partyLocationRole;
    LogisticsLocationRole   locationRole;
    LogisticsPostalAddress  postalAddress;        

    select firstonly Address            
        from postalAddress
        order by modifiedDateTime desc
        exists join locationRole
            where locationRole.Type  == _type
        exists join partyLocation
            where
                partyLocation.Location == postalAddress.Location &&
                partyLocation.Party == _party
        exists join partyLocationRole
            where partyLocationRole.PartyLocation == partyLocation.RecId &&
                partyLocationRole.LocationRole == locationRole.RecId;


    return postalAddress ? postalAddress.Address : '';
}
